def test_default_scope_extraction_ignores_raw_scope_claim_for_non_jwt_schemes(): # Regression: a raw ``scope`` claim on a non-JWT principal must not shadow # ``roles`` (would lock out a legitimately-authorized principal) nor be # matched as scope tokens (would escalate privileges). Only ``scopes`` and # ``roles`` are consulted generically. def verify(token): principals = { # roles grant admin; the OAuth2-style ``scope`` string must not # shadow it into a 403 lockout. "authorized": {"roles": ["admin"], "scope": "openid profile"}, # no roles/scopes; ``scope`` containing an "admin" token must not # escalate this principal into /admin. "attacker": {"roles": [], "scope": "admin:read admin"}, } return principals.get(token)
auth = BearerAuth(verify=verify).requires("admin") api = _api(auth=auth)
@api.get("/admin") def admin(req, resp, *, user): resp.media = {"ok": True}
client = _client(api) > assert client.get( "/admin", headers={"Authorization": "Bearer authorized"} ).status_code == 200
