def test_scope_extraction_survives_non_iterable_scope_value(): # Regression: a non-iterable scope/roles value must yield "no scopes", # never a 500. A principal with roles==5 simply satisfies no requirement. auth = BearerAuth( verify=lambda token: {"id": 1, "roles": 5} ).requires("admin") api = _api(auth=auth)
@api.get("/admin") def admin(req, resp, *, user): resp.media = {"ok": True}
open_auth = BearerAuth(verify=lambda token: {"id": 1, "roles": 5}) api2 = _api(auth=open_auth)
@api2.get("/open") def open_route(req, resp, *, user): resp.media = {"scopes": sorted(req.state.scopes)}
# Scoped route: non-iterable roles -> no scopes -> clean 403, not 500. > assert _client(api).get( "/admin", headers={"Authorization": "Bearer x"} ).status_code == 403
