def test_requires_helper_builds_scoped_auth_and_chains(): def verify(token): return {"admin": {"id": 1, "scopes": ["read", "write"]}}.get(token)
bearer = BearerAuth(verify=verify) scoped = bearer.requires("read").requires("write") assert isinstance(scoped, ScopedAuth) assert scoped.required_scopes == ("read", "write")
api = _api(auth=scoped)
@api.get("/items") def items(req, resp, *, user): resp.media = {"id": user["id"]}
client = _client(api) > assert client.get( "/items", headers={"Authorization": "Bearer admin"} ).json() == {"id": 1}
