def test_two_stacked_sync_middlewares_no_deadlock_under_concurrency(): """Two stacked sync middlewares each blocking on ``call_next`` (plus a sync view) previously deadlocked at roughly half the token budget.""" api = _live_api() barrier = threading.Barrier(_PARKED, timeout=15)
@api.middleware("http") def inner(request, call_next): return call_next(request)
@api.middleware("http") def outer(request, call_next): # Parking in the outermost body pins one worker thread per request; # the buggy version cannot gather _PARKED of them from the 40-token # shared pool. barrier.wait() return call_next(request)
