def test_route_local_hooks_are_scoped_and_ordered(): api = _api() seen = []
def global_before(req, resp): seen.append("global-before")
def local_before(req, resp): seen.append("local-before") req.state.local = True
def local_after(req, resp): seen.append("local-after") resp.headers["X-Local"] = "1"
def global_after(req, resp): seen.append("global-after")
api.before_request(global_before) api.after_request(global_after)
@api.get("/scoped", before=local_before, after=local_after) def scoped(req, resp): seen.append("handler") resp.media = {"local": req.state.local}
@api.get("/plain") def plain(req, resp): seen.append("plain") resp.media = {}
