def test_proxy_non_ascii_forwarded_port_does_not_crash(): api = _api(trust_proxy_headers=True, allowed_hosts=["*"])
@api.route("/where") async def where(req, resp): resp.media = {"host": req.headers["Host"]}
# ProxyHeadersMiddleware is outermost; an unhandled ValueError here would # send no response at all. The superscript-2 byte is valid latin-1 (0xB2). > r = api.requests.get( _url("/where"), headers={ "X-Forwarded-Proto": "https", # Raw latin-1 bytes: the test client refuses to ascii-encode a # non-ASCII header string, but a real proxy can send byte 0xB2. "X-Forwarded-Host": "example.com:8²".encode("latin-1"), }, )
