def test_non_ascii_content_length_is_not_500(): api = _api()
@api.route("/echo", methods=["POST"]) async def echo(req, resp): resp.media = {"len": len(await req.content)}
# A Content-Length of a superscript digit passes str.isdigit() but int() # would raise; the request must not 500. > r = api.requests.post( _url("/echo"), content=b"hi", headers={"Content-Length": "²".encode("latin-1")}, )
