def test_csrf_reregistration_does_not_strip_protection(): """Registering the same view a second time with csrf=False must not retroactively disable CSRF on its earlier, protected registration.""" api = _api(csrf=True)
async def handler(req, resp): resp.media = {"ok": True}
api.add_route("/pay", handler, methods=["POST"]) # inherits app csrf=True api.route("/webhook", methods=["POST"], csrf=False)(handler) # exempt alias
# /pay must still demand a token; /webhook must not. > assert api.requests.post(_url("/pay"), json={}).status_code == 403 ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
