def test_server_session_refreshes_ttl_on_read_only_request(make_api): # v5: a read-only request slides the backend TTL via touch() (not a full # re-serialize), while a mutation goes through set(). from responder.ext.sessions import MemorySessionBackend
backend = MemorySessionBackend() sets, touches = [], [] original_set, original_touch = backend.set, backend.touch backend.set = lambda sid, d, ttl: (sets.append(sid), original_set(sid, d, ttl))[1] backend.touch = lambda sid, ttl: (touches.append(sid), original_touch(sid, ttl))[1]
api = make_api(session_backend=backend)
